    ("TC-Anthropic", "https://techcrunch.com/2025/05/01/sources-anthropic-900b-valuation-round/"),
    ("TC-Pentagon", "https://techcrunch.com/2025/05/01/pentagon-nvidia-microsoft-aws-ai-classified-networks/"),
    ("TC-Legora", "https://techcrunch.com/2025/04/30/legal-ai-startup-legora-hits-5-6b-valuation/"),
    ("TC-Cowork", "https://venturebeat.com/ai/anthropic-launches-cowork-a-claude-desktop-agent-that-works-in-your-files-no-coding-required/"),
    ("TC-ListenLabs", "https://venturebeat.com/ai/listen-labs-raises-69m-after-viral-billboard-hiring-stunt-to-scale-ai-customer-interviews/"),
]

for name, url in pages:
    try:
        req = urllib.request.Request(url, headers={
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        })
        with urllib.request.urlopen(req, timeout=15) as r:
            content = r.read().decode('utf-8', errors='ignore')
        # Get meta description
        desc = re.findall(r'<meta[^>]*name="description"[^>]*content="([^"]+)"', content)
        if not desc:
            desc = re.findall(r'<meta[^>]*content="([^"]+)"[^>]*name="description"', content)
        og = re.findall(r'<meta[^>]*property="og:description"[^>]*content="([^"]+)"', content)
        if desc:
            print(f"{name}: {desc[0][:200]}")
        elif og:
            print(f"{name}: {og[0][:200]}")
        else:
            # Try first paragraph
            paras = re.findall(r'<p[^>]*>(.*?)</p>', content, re.DOTALL)
            for p in paras[:3]:
                p = re.sub(r'<[^>]+>', '', p).strip()
                if len(p) > 50:
                    print(f"{name}: {p[:200]}")
                    break
        print()
    except Exception as e:
        print(f"{name} error: {e}")
"}

